    30	/// Page-aligned allocator used for terminal page backing memory. Pages
    31	/// require page-aligned, zeroed memory obtained directly from the OS
    32	/// (not the Zig allocator) because the allocation fast-path is
    33	/// performance-critical and the OS guarantees zeroed pages.
    34	const PageAlloc = switch (builtin.target.os.tag) {
